diff --git a/internal/cli/watch.go b/internal/cli/watch.go
index 6a886b60..6a96d4d4 100644
--- a/internal/cli/watch.go
+++ b/internal/cli/watch.go
@@ -284,10 +284,13 @@ func watchTick(ctx context.Context, out io.Writer, w watchCommandOptions, cursor
 	cursor := loadWatchCursor(cursorPath)
 	// The hosted step pulls teammates' facts as much as it publishes local
 	// ones, so it must run on idle (no-change) ticks too — a machine that only
-	// receives would otherwise never sync. It is skipped on a failed refresh
-	// (callers below return before invoking it) and throttled by its own
-	// cursor timestamp, advanced regardless of outcome so a failing hosted
-	// endpoint cannot turn every tick into an egress attempt.
+	// receives would otherwise never sync. It runs on every exit path,
+	// including a failed refresh: a failed refresh never advances the main
+	// cursor, so a machine whose refresh always fails (e.g. the graph plugin
+	// is missing) takes that path on every tick and would otherwise be starved
+	// of the team's facts forever (COR-2114). It is token-free and throttled
+	// by its own cursor timestamp, advanced regardless of outcome so a failing
+	// hosted endpoint cannot turn every tick into an egress attempt.
 	runFactsSync := func() {
 		now := steps.now().UTC()
 		if steps.factsSync == nil || now.Sub(cursor.LastFactsSyncAt) < hostedSyncMinInterval {
@@ -339,7 +342,9 @@ func watchTick(ctx context.Context, out io.Writer, w watchCommandOptions, cursor
 		if err := steps.refresh(ctx); err != nil {
 			// Refresh failed: do NOT spend tokens on an unrefreshed brain, and do NOT advance the cursor.
 			// The next tick retries the free refresh before attempting pending agent work.
+			// Hosted fact sync is not agent work and must not starve with refresh.
 			fmt.Fprintf(out, "[watch] refresh failed (skipping agent work this tick): %v\n", err)
+			runFactsSync()
 			return
 		}
 	}
diff --git a/internal/cli/watch_hosted_test.go b/internal/cli/watch_hosted_test.go
index dae4ea3c..3f59346b 100644
--- a/internal/cli/watch_hosted_test.go
+++ b/internal/cli/watch_hosted_test.go
@@ -28,7 +28,7 @@ func TestWatchTickRunsHostedSyncAfterRefresh(t *testing.T) {
 	}
 }

-func TestWatchTickSkipsHostedSyncWhenRefreshFails(t *testing.T) {
+func TestWatchTickRunsHostedSyncWhenRefreshFails(t *testing.T) {
 	cursorPath := filepath.Join(t.TempDir(), "watch.json")
 	var refreshed, seeded, distilled, synced int
 	steps := fakeWatchSteps("ck1:head1", &refreshed, &seeded, &distilled)
@@ -36,9 +36,18 @@ func TestWatchTickSkipsHostedSyncWhenRefreshFails(t *testing.T) {
 	steps.factsSync = func(context.Context) error { synced++; return nil }
 	var out bytes.Buffer
 	var agentCalls int
+	// A failed refresh never advances the main cursor, so on a machine whose
+	// refresh always fails every tick takes this path: hosted sync must still
+	// run or the member never receives teammates' facts (COR-2114).
 	watchTick(context.Background(), &out, watchCommandOptions{}, cursorPath, steps, &agentCalls)
-	if synced != 0 {
-		t.Fatalf("hosted sync must not run when refresh failed, got %d", synced)
+	if synced != 1 {
+		t.Fatalf("hosted sync must run even when refresh failed, got %d", synced)
+	}
+	if !strings.Contains(out.String(), "refresh failed (skipping agent work this tick)") {
+		t.Fatalf("refresh failure must still skip agent work, got %q", out.String())
+	}
+	if readWatchCursor(t, cursorPath).LastFactsSyncAt.IsZero() {
+		t.Fatal("cursor must record the sync attempt so the throttle applies")
 	}
 }

